CREATE OR REPLACE FUNCTION public.aka_agent_block_denied_ip_request()
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_headers jsonb := COALESCE(
    NULLIF(pg_catalog.current_setting('request.headers', true), '')::jsonb,
    '{}'::jsonb
  );
  v_candidate text;
  v_ip inet;
BEGIN
  -- Cloudflare supplies cf-connecting-ip on this project's live API route.
  -- Inspect all forwarded candidates as well, so supplying a different
  -- client-controlled forwarded value cannot hide a denied originating hop.
  -- No writes: this also works for GET/HEAD read-only transactions.
  FOREACH v_candidate IN ARRAY pg_catalog.string_to_array(
    pg_catalog.concat_ws(',',
      v_headers ->> 'cf-connecting-ip',
      v_headers ->> 'x-real-ip',
      v_headers ->> 'x-forwarded-for'
    ), ','
  ) LOOP
    v_candidate := pg_catalog.btrim(v_candidate);
    IF v_candidate = '' THEN
      CONTINUE;
    END IF;

    BEGIN
      v_ip := v_candidate::inet;
    EXCEPTION WHEN invalid_text_representation THEN
      CONTINUE;
    END;

    IF pg_catalog.host(v_ip) IN ('14.254.197.100', '::ffff:14.254.197.100') THEN
      RAISE SQLSTATE 'PT403' USING MESSAGE = 'Access denied';
    END IF;
  END LOOP;
END;
$function$

